pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tightest fit (Best-Fit)
    let mut score = post_residual as f64 * 0.8;

    // 1. Lookahead Synergy: Exponentially reward placements that accommodate the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64).powf(1.35) * (1.1 - progress * 0.2);
    }

    // 2. Adaptive New-Bin Thresholding
    // If the item is large (> 60% capacity), we are more tolerant of opening a new bin
    // to preserve capacity in partially filled bins for smaller, more flexible items.
    if is_new_bin {
        if open_bins_count == 0 {
            score = -100.0;
        } else {
            // New bin cost is scaled by the scarcity of space in existing bins
            let density_pressure = (mean_residual / bin_capacity as f64) * 40.0;
            let size_urgency = if item_size > (bin_capacity / 2) { -15.0 } else { 15.0 };
            score += density_pressure + size_urgency + (progress * 10.0);
        }
    } else {
        // 3. Fragmentation Penalty
        // Penalize placing items that create "dead zones" (residuals too small for common items)
        if post_residual > 0 && post_residual < 8 {
            score += (10.0 - post_residual as f64) * (1.0 + progress);
        }

        // 4. Fitting Bin Scarcity
        // If this is the only bin that can hold this item, lower the score to prioritize it
        if fitting_bins_count == 1 {
            score -= 20.0 * (1.0 - progress * 0.5);
        }
    }

    // 5. Tail-end optimization: As we approach the end, prioritize closing bins
    // by being aggressive on packing into existing residual space.
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
}

