pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit: penalize large post_residuals (wasted space)
    // 2. Harmonic Penalty: If post_residual is small but not zero, it creates "dead zones"
    //    that cannot fit the minimum item size (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead logic: if next_item_size is large, favor larger residuals now
    //    to accommodate the future item, preventing premature bin opening.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize tightly packing this item if it forces a new bin for the next
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 4. Harmonic capacity balancing:
    //    If this is the only bin that fits, we are forced to take it.
    //    If we are considering a new bin (bin_residual == bin_capacity), 
    //    heavily penalize it unless the existing bins are extremely crowded.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open new if the mean residual of existing bins is very low (< 15)
            if mean_residual > 15.0 {
                score += 200.0; 
            } else {
                score += 5.0; 
            }
        }
    }

    // 5. Modulo-based "Perfect Fit" reward:
    //    If post_residual is 0, this is a perfect fit. 
    //    Subtract score to make it the most attractive option.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 6. Scale by progression: As we near the end of the stream, 
    //    be more aggressive about filling bins (reduce score).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: non-linear gap penalty
    let mut score = (post_residual as f64).powf(1.52);

    // 1. Lookahead Synergy: Refined reward for packing next_item_size
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward better usage: prioritize leaving room for the next item
            score -= (next_item_size as f64).powf(1.8) * (1.05 - progress * 0.2);
            // Additional reward for tight fits to minimize splinter residuals
            score -= 18.0 / (slack + 1.0);
        } else {
            // Penalize inability to fit next item, softened by progression
            score += 15.0 * (1.0 - progress * 0.4);
        }
    }

    // 2. Adaptive New-Bin Thresholding
    if is_new_bin {
        if open_bins_count == 0 {
            score = -600.0;
        } else {
            // New bin cost is scaled by the scarcity of space (mean_residual)
            // Penalize opening new bins if the average remaining capacity is high.
            let density_pressure = (mean_residual / bin_capacity as f64) * 95.0;
            // Encourage filling large items into new bins only if necessary
            let size_urgency = if item_size > (bin_capacity * 65 / 100) { -45.0 } else { 40.0 };
            let count_penalty = (open_bins_count as f64).ln() * 15.0;
            score += density_pressure + size_urgency + (progress * 35.0) + count_penalty;
        }
    } else {
        // 3. Fragmentation Penalty: Avoid creating "dead zones" (residuals < 14)
        if post_residual > 0 && post_residual < 14 {
            score += (16.0 - post_residual as f64) * (1.5 + progress);
        }

        // 4. Scarcity/Fitting Pressure: If this is the only bin that can hold this item, 
        // give it a massive priority boost to prevent an unnecessary new bin opening.
        if fitting_bins_count == 1 {
            score -= 65.0 * (1.0 - progress * 0.1);
        }

        // 5. Residual Variance: Penalize large deviations from the mean to keep bins uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.55;
    }

    // 6. Tail-end optimization: As we approach the end, prioritize bin consolidation.
    if progress > 0.82 {
        if is_new_bin {
            score += 130.0 + (progress * 50.0);
        } else {
            // Reward finishing existing bins to reduce open_bins_count
            score -= (bin_capacity - post_residual) as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. Smaller is generally better (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (small residuals that are unlikely to fit future items).
    // If post_residual is < 10, it's very hard to pack anything else.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, prefer bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty if this choice prevents fitting the next item
            score += 15.0;
        } else {
            // Reward if this choice preserves space for the next item
            score -= 5.0;
        }
    }

    // Dynamic thresholding for new bins:
    // Avoid opening new bins unless the fit is truly bad or we are near the end of the stream.
    if is_new_bin {
        if fitting_bins_count == 0 {
            // Must open a new bin, return low score.
            score = -50.0;
        } else {
            // Only open new if the average residual is very high (meaning bins are mostly empty)
            // or if we are at the very end of the stream.
            let threshold = 40.0 + (20.0 * progress);
            if mean_residual > threshold {
                score = -10.0;
            } else {
                // Heavily penalize opening a new bin unnecessarily
                score = 200.0;
            }
        }
    } else {
        // If it's an existing bin, favor bins that are already 'tight' to keep others open.
        // Penalty proportional to how much space we are 'wasting' relative to the mean.
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress
    // As we near the end of the stream, we are more desperate to close bins
    if is_new_bin {
        score += 15.0 + (progress * 30.0);
    }

    // Lookahead logic: If the next item is large, prefer bins that can accommodate it 
    // or maximize the chance of fitting it in existing space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for "double fit" (current + next)
            score -= 25.0;
        } else if post_residual > 0 && post_residual < 20 {
            // Penalty for creating "slivers" that cannot fit common items
            score += 15.0;
        }
    }

    // Global state optimization:
    // If we have many open bins, penalize opening new ones.
    // If mean_residual is low, we are packing tightly; maintain that pressure.
    if !is_new_bin {
        score += (open_bins_count as f64 * 0.5);
        if (post_residual as f64) < mean_residual {
            score -= 5.0; // Reward packing tighter than average
        }
    }

    // Critical threshold: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

