    // If the post_residual is < 10, it's likely "dead space" because items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bin Pressure: Penalize opening new bins when existing ones can accommodate the item.
    // If this is a new bin (bin_residual == bin_capacity) and other bins could fit it, punish it.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 3. Next Item Lookahead: If the next item is large, avoid leaving a residual smaller than next_item_size.
    // This prevents creating a bin that cannot accommodate the next known arrival.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 4. Density Balancing: Favor bins that stay close to the current mean residual to keep bins "equally full".
    // This helps avoid scattered fragmented bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Global Pressure: As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a significant penalty to favor packing into existing bins.
    // The penalty decreases as we reach the end of the stream to allow for final cleanup.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 * (1.0 - progress * 0.5);
