    // 2. 2-step Lookahead: If the post_residual is close to the next_item_size, 
    // it is a high-value placement.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward placements that leave a residual perfectly sized for the next item
        score -= (25.0 / (1.0 + diff)) * 2.0;
    }

    // 3. Efficiency heuristic: penalize creating "tiny" residuals (dead space) that are hard to fill.
    // If post_residual is < 10, it's likely wasted unless it perfectly matches next_item_size.
    if post_residual < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    // 4. Mean Residual balancing: avoid bins that deviate too far from the average state.
    let residual_dev = (post_residual as f64 - mean_residual).abs();
    score += residual_dev * 0.1;

    // 5. Urgency: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
