        score += 35.0;

        // If we are at the end of the stream, the cost of a new bin is relatively lower 
        // compared to trying to force a bad fit into a nearly full bin.
        score -= (progress * 20.0);

        // If no other bin can fit this item, force the new bin.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Encourage using bins that are already closer to the mean residual to keep
        // the remaining space distribution uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;

        // If this is the only bin that can fit the item, strongly prioritize it.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

