    // especially as the stream progresses and options vanish.
    let gap_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.0 + 2.0 * progress)
    } else {
        0.0
    };

    // Factor in the lookahead: if the next item is large, prioritize keeping 
    // space open (lower post_residual is better for current, but higher is better for future).
    let lookahead_impact = if next_item_size > 0 {
        let fit_next = (post >= next_item_size as f64) as i32 as f64;
        (1.0 - fit_next) * (next_item_size as f64 / 100.0) * 15.0
    } else {
        0.0
    };

