    } else {
        0.0
    };

    // Calculate base score: lower post_residual is usually Best Fit (good for packing).
    // Add non-linear interaction between current fill and stream progress.
    let mut score = post + gap_penalty + lookahead_impact + urgency_multiplier;

    // Discourage opening new bins (bin_residual == bin_capacity) unless necessary.
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // We penalize post_residuals that create "orphaned" gaps that cannot fit common item sizes.
    // We prioritize keeping the residual as close to the next_item_size as possible to maximize bin density.

    let mut score = post_residual as f64;

    // 1. Harmonic penalty: Penalize residuals that are small but not zero (the "fragmentation" zone).
    // If post_residual is in [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
