            score += gap * 0.5;
        } else {
            // Penalty for making the next item impossible to fit in this bin
            score += 20.0;
        }
    }

    // 3. Density balancing: If we have many open bins, penalize opening a new one unless it's a perfect fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one can take the item
            score += 60.0;
        }
        // If it's a new bin, reward based on how much of the bin we fill (Higher fill = lower score)
        score -= (item_size as f64) * 0.2;
    }

    // 4. Harmonic class bias: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 50).
    // This reduces the chance of creating unusable fragments.
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
