    // Base score: Optimize for tight fit using a quadratic penalty for large residuals
    // and a exponential penalty for tiny "unusable" gaps.
    let mut score = (post_residual as f64).powf(1.6);

    // 1. Lookahead Synergy: Dynamic lookahead weighting.
    // If the next item fits perfectly, reward it more aggressively as we progress.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_diff = (post_residual - next_item_size) as f64;
        let lookahead_reward = (next_item_size as f64 * 3.2) + (15.0 / (fit_diff + 1.0));
        score -= lookahead_reward * (1.0 + progress);
    }

    // 2. Adaptive New-Bin Thresholding:
    // Penalize new bin creation based on the ratio of current capacity utilization.
    if is_new_bin {
        if open_bins_count == 0 {
            score = -500.0; 
        } else {
            // Threshold based on how much "slack" is currently available in open bins.
            // If mean_residual is low, we have space, so discourage opening new bins.
            let slack_penalty = (mean_residual * 2.5) + (progress * 45.0);
            score += slack_penalty;

            // If we have many fitting options for the current item, opening a new bin is 
            // almost certainly suboptimal.
            score += (fitting_bins_count as f64) * 8.0;
        }
    } else {
        // 3. Fragmentation Control:
        // Heavily penalize "dead zones" (residuals 1-7) that are unlikely to be filled.
        if post_residual > 0 && post_residual < 8 {
            score += 22.0 * (1.0 - progress * 0.5);
        }

        // 4. Fitting Pressure:
        // Balance the distribution by preferring bins that are already "semi-full"
        // (residual < 40% of capacity) to prevent creating many half-empty bins.
        let usage_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        if usage_ratio < 0.4 {
            score += 5.0;
        }
    }

    // 5. Tail-End Heuristic:
    // As we approach the end, the cost of opening a new bin is extremely high.
    if progress > 0.92 {
        if is_new_bin {
            score += 150.0;
        } else {
            // In the final phase, prioritize filling the bin with the smallest residual.
            score -= (bin_residual as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core objective: minimize post_residual, but apply non-linear penalty for "dead zones" (1-15)
    // where items are unlikely to fit, effectively pushing for either tight packing or large gaps.
    let mut score = (post_residual as f64).powf(1.45);
    if post_residual > 0 && post_residual < 16 {
        score += 8.0 * (1.0 - progress.powi(2));
    }

    // Lookahead: prioritize placements that align with next_item_size.
    // If next_item_size fits perfectly, we subtract a significant reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // Reward exact fit (gap 0) much higher than loose fit.
            score -= (next_item_size as f64 * 3.2) + (15.0 / (gap as f64 + 1.0)).powf(1.2);
        }
    }

    if is_new_bin {
        if open_bins_count == 0 {
            score = -500.0; 
        } else {
            // Adaptive threshold for opening a new bin:
            // Penalize new bin based on current mean_residual efficiency.
            // If mean_residual is low, we are packing tightly, so don't open new bins easily.
            let efficiency_penalty = (mean_residual * 2.2) + (progress * 25.0);
            score += efficiency_penalty;

            // As we approach the end of the stream, discourage opening new bins.
            if progress > 0.85 {
                score += 65.0 * (progress - 0.85) / 0.15;
            }
        }
    } else {
        // Fragmentation Control:
        // Bias towards bins that maintain the mean residual balance.
        // If fitting_bins_count is high, we have many choices; use the one that minimizes
        // the deviation from the current mean_residual.
        let residual_deviation = (bin_residual as f64 - mean_residual).abs();
        score -= (fitting_bins_count as f64).sqrt() * 1.5;
        score += residual_deviation * 0.1;
    }

    // Final entropy regulator: prevent extreme bin counts by penalizing high open_bins_count
    // relative to the expected bin count (assuming ~85% packing efficiency).
    let expected_bins = (total_items as f64 * 50.0) / (bin_capacity as f64 * 0.85);
    if open_bins_count as f64 > expected_bins * 1.2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin early in the stream, but allow it if it's the only option.
    // The "new bin" candidate has bin_residual == bin_capacity (100).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Calculate a "fit quality" score. Lower is better.
    // We prefer post_residual to be small (tight fit) but not zero if it prevents 
    // future items from fitting.
    // We use a non-linear penalty for "dead space" (post_residual).
    let mut score = post * 1.5;

    // Favor bins that leave space for the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Severe penalty if we block the next item from fitting here
            score += 40.0 * (1.0 - progress);
        } else {
            // Reward if we leave just enough room for the next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64)).sqrt();
        }
    }

    // Encourage filling bins that are already partially filled (low mean_residual)
    // to consolidate space.
    score += (bin_residual as f64 - mean_residual).abs() * 0.5;

    // If this is the last fitting bin, prioritize it to avoid unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
