    let mut score = (post_residual as f64).powf(1.65);

    // 1. Predictive Lookahead: 
    // Reward bins that create a 'perfect' fit for the next item, 
    // but penalize creating a 'sliver' (residual < 5) that isn't useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let space_after_next = post_residual - next_item_size;
            if space_after_next == 0 {
                score -= 45.0; // Perfect sync
            } else if space_after_next < 5 {
                score += 15.0; // Avoid creating unfillable slivers
            } else {
                score -= (next_item_size as f64 * 1.8);
            }
        }
    }

    // 2. Adaptive New-Bin Thresholding:
    // Dynamically adjust the cost of opening a new bin based on current system entropy.
    if is_new_bin {
        if open_bins_count == 0 {
            score = -500.0; 
        } else {
            // Tighten the threshold for new bins as we progress.
            // If mean_residual is low, we are packing well; don't disrupt it.
            let efficiency_bias = (mean_residual.powf(0.8)) * 4.0;
            let time_decay = progress * 40.0;
            score += 35.0 + efficiency_bias + time_decay;
        }
    } else {
        // 3. Fragmentation Management:
        // Penalize bins that are becoming 'orphaned' (low fitting potential).
        // If the bin is already quite full, reward it for staying 'tight'.
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fill_ratio * 12.0;

        // 4. Fitting Pressure:
        // If an item has many options, prefer the ones that keep the residual 
        // variance low. We use the log of fitting_bins to temper the influence.
        if fitting_bins_count > 1 {
            score -= (fitting_bins_count as f64).ln() * 3.5;
        }
    }

    // 5. Tail-End Heuristic:
    // In the final 15% of the stream, prioritize closing gaps in existing bins 
    // over opening new ones aggressively.
    if progress > 0.85 {
        if is_new_bin {
            score += 85.0;
        } else {
            score -= (1.0 / (post_residual as f64 + 0.1)) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
