    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Linear penalty for remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // 1. Lookahead Synergy: Anticipatory fit
    // Prioritize bins that leave a residual capable of holding the next item, 
    // especially if that residual is close to the next item size (reducing fragmentation).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // Reward exact matches or near-exact matches for the next item
            score -= (40.0 - (slack as f64 * 1.5)) * (1.0 - progress * 0.2);
        } else {
