        }

        // 5. Balance/Variance:
        // Keep residuals close to the mean to maintain uniform bin utilization.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.35;
    }

    // 6. Tail-end consolidation: 
    // In the final 10% of items, prioritize filling existing bins over opening new ones.
    if progress > 0.90 {
        if is_new_bin {
            score += 200.0;
        } else {
            score -= (bin_capacity - post_residual) as f64 * 0.2;
