        score += (post_residual as f64) * 0.75;
    }

    // 7. Density Optimization: Favor bins that reach high utilization
    // Penalize low-density bins to push items into "heavy" bins
    if !is_new_bin {
        if post_filled < (bin_capacity / 4) {
            score += 40.0;
        } else if post_filled > (bin_capacity * 3 / 4) {
            score -= 35.0;
        }
    }

    // 8. Global Efficiency Bias: Reward high utilization (non-linear)
    score -= (post_filled as f64).powf(1.15) * 0.04;

    score
}

pub fn score_bin(
