            score -= 160.0; 
        } else if post_residual > next_item_size && post_residual < (next_item_size + 14) {
            score -= 75.0;  
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 85.0;  // Stiffer penalty for stranding items
        }
    }

    // 2. Adaptive New-Bin Thresholding:
    // Increased resistance to opening new bins to force better consolidation
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Increased threshold to force usage of existing bins
            score += 315.0 + (progress * 240.0) + (open_bins_count as f64 * 2.5);
        } else {
            score = 6.0 + (mean_residual * 0.10);
        }
    } else {
        // 3. Fragmentation Penalty: Target "Dead Zones" (1-26)
        if post_residual > 0 && post_residual < 26 {
            score += 105.0 + (progress * 65.0);
        }

        // 4. Scarcity Pressure: Prioritize unique fits more heavily
        if fitting_bins_count == 1 {
            score -= 130.0 * (1.0 - progress * 0.06);
        }

        // 5. Residual Variance: Penalize deviations from global mean
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 1.10;
    }

    // 6. Tail-end consolidation: Force aggressive compaction near completion
    if progress > 0.85 {
        score += (post_residual as f64) * 8.0;
    } else if progress > 0.40 {
        score += (post_residual as f64) * 0.85;
    }

    // 7. Small Item Logic: Force small items into fuller bins
    // Adjusted logic to preserve larger gaps for potential large items
    if !is_new_bin && item_size < 40 && (bin_capacity - bin_residual) < (bin_capacity / 2) {
        score -= 45.0;
    }

    // 8. Global Efficiency Bias: Reward high utilization (penalize residual)
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps (1-9)
    // that are unlikely to fit future items, while accounting for the lookahead.

    let mut score = post_residual as f64;

    // Penalty for creating a "fragmented" bin: if the remaining space is too small 
    // for almost any item (e.g., < 10), we treat it as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // If this is a new bin, penalize it based on how many other bins are already open.
    // This forces the algorithm to exhaust existing capacity before opening new bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // Lookahead logic: if the next item is large, favor bins that have enough space 
    // to accommodate it (post_residual >= next_item_size).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // If this is the last chance to fit the item in an existing bin, reward it 
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Favor bins that are closer to the mean residual to maintain uniform bin usage.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    score
}

